/**
 * Raven - platform/wayland/wayland_platform.c
 * Native Wayland implementation of the platform interface (Linux, BSD),
 * compiled beside the X11 one: rvn_platform_select picks Wayland when the
 * session is a Wayland session, X11 otherwise (or through XWayland).
 *
 * Nothing of Wayland is needed to build it: libwayland-client, libxkbcommon
 * and, when present, libwayland-cursor and libdecor are opened at run time,
 * and the protocols are compiled in (wayland_protocols.h, generated by
 * tools/wayland/gen_wayland.py).
 *
 *   - windows: xdg-shell, decorations drawn by the compositor
 *     (xdg-decoration) or, where it draws none (GNOME), by libdecor,
 *   - fractional scales (fractional-scale-v1 + viewporter), integer
 *     scales otherwise,
 *   - keyboard through xkbcommon: layouts, key repeat, dead keys and
 *     compose sequences,
 *   - pointer, wheel and touchpad scrolling; cursors from cursor-shape-v1
 *     or from the cursor theme,
 *   - clipboard and files or text dropped from other applications
 *     (wl_data_device),
 *   - sub-surfaces for native viewports, window icons (xdg-toplevel-icon),
 *     blur behind transparent windows (ext-background-effect).
 *
 * Wayland does not let a client place its windows or know where they are:
 * window_set_position and window_center do nothing, window_get_position
 * gives 0, 0.
 */

#include "../platform.h"
#include "../atspi.h"
#include "../x11/x11_internal.h"   /* the key symbols of X11 and of xkbcommon are the same numbers */

#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <locale.h>
#include <poll.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>

/* ---------------------------------------------------------------------------
 *  libwayland-client, opened at run time
 *
 *  The few types of wayland-util.h that the protocol tables need, with the
 *  layout of the library (stable since Wayland 1.0).
 * ------------------------------------------------------------------------- */

struct wl_proxy;
struct wl_display;

struct wl_message {
	const char* name;
	const char* signature;
	const struct wl_interface** types;
};

struct wl_interface {
	const char* name;
	int version;
	int method_count;
	const struct wl_message* methods;
	int event_count;
	const struct wl_message* events;
};

struct wl_array {
	size_t size;
	size_t alloc;
	void* data;
};

static struct {
	void* library;
	struct wl_proxy* (*proxy_marshal_flags)(struct wl_proxy* proxy, uint32_t opcode, const struct wl_interface* interface,
		uint32_t version, uint32_t flags, ...);
	int (*proxy_add_listener)(struct wl_proxy* proxy, void (**implementation)(void), void* data);
	void (*proxy_destroy)(struct wl_proxy* proxy);
	uint32_t (*proxy_get_version)(struct wl_proxy* proxy);
	void (*proxy_set_user_data)(struct wl_proxy* proxy, void* data);
	void* (*proxy_get_user_data)(struct wl_proxy* proxy);
	struct wl_display* (*display_connect)(const char* name);
	void (*display_disconnect)(struct wl_display* display);
	int (*display_get_fd)(struct wl_display* display);
	int (*display_dispatch_pending)(struct wl_display* display);
	int (*display_prepare_read)(struct wl_display* display);
	int (*display_read_events)(struct wl_display* display);
	void (*display_cancel_read)(struct wl_display* display);
	int (*display_flush)(struct wl_display* display);
	int (*display_roundtrip)(struct wl_display* display);
	int (*display_get_error)(struct wl_display* display);
} g_wlc;

#define RVN_WL_MARSHAL g_wlc.proxy_marshal_flags
#define RVN_WL_MARSHAL_FLAG_DESTROY (1 << 0)
#define RVN_WL_ADD_LISTENER g_wlc.proxy_add_listener
#define RVN_WL_PROXY_DESTROY g_wlc.proxy_destroy
#define RVN_WL_GET_VERSION g_wlc.proxy_get_version
#define RVN_WL_SET_USER_DATA g_wlc.proxy_set_user_data
#define RVN_WL_GET_USER_DATA g_wlc.proxy_get_user_data

#include "wayland_protocols.h"

static double rvn_wl_fixed(int32_t value) {
	return (double)value / 256.0;
}

