/* Resolves a symbol into a function pointer (the C standard keeps the two kinds of pointer apart). */
static int rvn_wl_symbol(void* library, const char* name, void* function) {
	void* symbol = library ? dlsym(library, name) : NULL;
	memcpy(function, &symbol, sizeof(void*));
	return symbol != NULL;
}

static void* rvn_wl_open(const char* name, const char* fallback) {
	void* library = dlopen(name, RTLD_NOW | RTLD_LOCAL);
	if (!library && fallback) library = dlopen(fallback, RTLD_NOW | RTLD_LOCAL);
	return library;
}

static int rvn_wl_load_client(void) {
	int ok = R_TRUE;
	if (g_wlc.library) return R_TRUE;
	g_wlc.library = rvn_wl_open("libwayland-client.so.0", "libwayland-client.so");
	if (!g_wlc.library) return R_FALSE;
#define RVN_LOAD(field, name) ok &= rvn_wl_symbol(g_wlc.library, name, &g_wlc.field)
	RVN_LOAD(proxy_marshal_flags, "wl_proxy_marshal_flags");   /* Wayland 1.20 (2021) */
	RVN_LOAD(proxy_add_listener, "wl_proxy_add_listener");
	RVN_LOAD(proxy_destroy, "wl_proxy_destroy");
	RVN_LOAD(proxy_get_version, "wl_proxy_get_version");
	RVN_LOAD(proxy_set_user_data, "wl_proxy_set_user_data");
	RVN_LOAD(proxy_get_user_data, "wl_proxy_get_user_data");
	RVN_LOAD(display_connect, "wl_display_connect");
	RVN_LOAD(display_disconnect, "wl_display_disconnect");
	RVN_LOAD(display_get_fd, "wl_display_get_fd");
	RVN_LOAD(display_dispatch_pending, "wl_display_dispatch_pending");
	RVN_LOAD(display_prepare_read, "wl_display_prepare_read");
	RVN_LOAD(display_read_events, "wl_display_read_events");
	RVN_LOAD(display_cancel_read, "wl_display_cancel_read");
	RVN_LOAD(display_flush, "wl_display_flush");
	RVN_LOAD(display_roundtrip, "wl_display_roundtrip");
	RVN_LOAD(display_get_error, "wl_display_get_error");
#undef RVN_LOAD
	if (!ok) {
		dlclose(g_wlc.library);
		memset(&g_wlc, 0, sizeof(g_wlc));
	}
	return ok;
}

static int rvn_wl_load_xkb(void) {
	int ok = R_TRUE;
	if (g_xkb.library) return R_TRUE;
	g_xkb.library = rvn_wl_open("libxkbcommon.so.0", "libxkbcommon.so");
	if (!g_xkb.library) return R_FALSE;
#define RVN_LOAD(field, name) ok &= rvn_wl_symbol(g_xkb.library, name, &g_xkb.field)
	RVN_LOAD(context_new, "xkb_context_new");
	RVN_LOAD(context_unref, "xkb_context_unref");
	RVN_LOAD(keymap_new_from_string, "xkb_keymap_new_from_string");
	RVN_LOAD(keymap_unref, "xkb_keymap_unref");
	RVN_LOAD(keymap_mod_get_index, "xkb_keymap_mod_get_index");
	RVN_LOAD(keymap_key_repeats, "xkb_keymap_key_repeats");
	RVN_LOAD(keymap_key_get_syms_by_level, "xkb_keymap_key_get_syms_by_level");
	RVN_LOAD(state_new, "xkb_state_new");
	RVN_LOAD(state_unref, "xkb_state_unref");
	RVN_LOAD(state_update_mask, "xkb_state_update_mask");
	RVN_LOAD(state_key_get_one_sym, "xkb_state_key_get_one_sym");
	RVN_LOAD(state_key_get_utf32, "xkb_state_key_get_utf32");
	RVN_LOAD(state_key_get_layout, "xkb_state_key_get_layout");
	RVN_LOAD(state_mod_index_is_active, "xkb_state_mod_index_is_active");
#undef RVN_LOAD
	if (!ok) {
		dlclose(g_xkb.library);
		memset(&g_xkb, 0, sizeof(g_xkb));
		return R_FALSE;
	}
	/* compose: all or nothing */
	if (!rvn_wl_symbol(g_xkb.library, "xkb_compose_table_new_from_locale", &g_xkb.compose_table_new_from_locale) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_table_unref", &g_xkb.compose_table_unref) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_state_new", &g_xkb.compose_state_new) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_state_unref", &g_xkb.compose_state_unref) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_state_feed", &g_xkb.compose_state_feed) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_state_reset", &g_xkb.compose_state_reset) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_state_get_status", &g_xkb.compose_state_get_status) ||
		!rvn_wl_symbol(g_xkb.library, "xkb_compose_state_get_utf8", &g_xkb.compose_state_get_utf8)) {
		g_xkb.compose_table_new_from_locale = NULL;
	}
	return R_TRUE;
}

static void rvn_wl_load_cursor(void) {
	if (g_wlcursor.library) return;
	g_wlcursor.library = rvn_wl_open("libwayland-cursor.so.0", "libwayland-cursor.so");
	if (!g_wlcursor.library) return;
	if (!rvn_wl_symbol(g_wlcursor.library, "wl_cursor_theme_load", &g_wlcursor.theme_load) ||
		!rvn_wl_symbol(g_wlcursor.library, "wl_cursor_theme_destroy", &g_wlcursor.theme_destroy) ||
		!rvn_wl_symbol(g_wlcursor.library, "wl_cursor_theme_get_cursor", &g_wlcursor.theme_get_cursor) ||
		!rvn_wl_symbol(g_wlcursor.library, "wl_cursor_image_get_buffer", &g_wlcursor.image_get_buffer)) {
		dlclose(g_wlcursor.library);
		memset(&g_wlcursor, 0, sizeof(g_wlcursor));
	}
}

