/* ---------------------------------------------------------------------------
 *  Helpers
 * ------------------------------------------------------------------------- */

static void rvn_wl_emit(rvn_pwindow_t* window, rvn_pevent_t* event) {
	event->user = window->user;
	g_wl.handler(event);
}

static int rvn_wl_round(float value) {
	return (int)floorf(value + 0.5f);
}

/* What a mime type is to Raven. */
static uint32_t rvn_wl_mime(const char* mime) {
	if (strcmp(mime, "text/plain;charset=utf-8") == 0 || strcmp(mime, "UTF8_STRING") == 0) return RVN_WL_MIME_TEXT_UTF8;
	if (strcmp(mime, "text/plain") == 0 || strcmp(mime, "TEXT") == 0 || strcmp(mime, "STRING") == 0) return RVN_WL_MIME_TEXT;
	if (strcmp(mime, "text/uri-list") == 0) return RVN_WL_MIME_URI_LIST;
	return 0;
}

/* The mime types offered by a wl_data_offer are kept in its user data, as bits. */
static uint32_t rvn_wl_offer_mimes(struct wl_data_offer* offer) {
	return offer ? (uint32_t)(uintptr_t)wl_data_offer_get_user_data(offer) : 0u;
}

/* A file descriptor of anonymous memory, for buffers shared with the compositor. */
static int rvn_wl_shared_memory(size_t size) {
	int fd = -1;
#if defined(__linux__)
	fd = (int)memfd_create("raven", MFD_CLOEXEC);
#endif
	if (fd < 0) {
		char path[] = "/tmp/raven-XXXXXX";
		fd = mkstemp(path);
		if (fd >= 0) {
			unlink(path);
			fcntl(fd, F_SETFD, FD_CLOEXEC);
		}
	}
	if (fd < 0) return -1;
	if (ftruncate(fd, (off_t)size) != 0) {
		close(fd);
		return -1;
	}
	return fd;
}

/* ---------------------------------------------------------------------------
 *  Scale
 *
 *  With viewporter (every current compositor) the buffer keeps a scale of 1
 *  and the viewport shows it at the logical size of the window: any scale,
 *  fractional or not, and a frame of the old size during a change is only
 *  stretched. Without it, the integer buffer scale of wl_surface.
 * ------------------------------------------------------------------------- */

static float rvn_wl_wanted_scale(rvn_pwindow_t* window) {
	int i, best = 0;
	if (window->scale120 > 0 && g_wl.viewporter) return (float)window->scale120 / 120.0f;
	if (window->preferred_buffer_scale > 0) return (float)window->preferred_buffer_scale;
	for (i = 0; i < window->output_count; i++) {
		int k;
		for (k = 0; k < g_wl.output_count; k++) {
			if (g_wl.outputs[k].output == window->outputs[i] && g_wl.outputs[k].scale > best) best = g_wl.outputs[k].scale;
		}
	}
	if (best > 0) return (float)best;
	/* not on an output yet: guess the largest scale of the screens */
	for (i = 0; i < g_wl.output_count; i++) best = rvn_maxi(best, g_wl.outputs[i].scale);
	return (float)rvn_maxi(best, 1);
}

/* The size of the surface changed, or its scale: tell the compositor how to show the buffer. */
static void rvn_wl_update_geometry(rvn_pwindow_t* window) {
	if (window->viewport) {
		wp_viewport_set_destination(window->viewport, rvn_maxi(window->width, 1), rvn_maxi(window->height, 1));
	} else if (!window->is_child) {
		wl_surface_set_buffer_scale(window->surface, window->buffer_scale);
	}
	if (!window->transparent && !window->is_child) {
		struct wl_region* region = wl_compositor_create_region(g_wl.compositor);
		wl_region_add(region, 0, 0, window->width, window->height);
		wl_surface_set_opaque_region(window->surface, region);
		wl_region_destroy(region);
	}
	if (window->effect) {
		struct wl_region* region = wl_compositor_create_region(g_wl.compositor);
		wl_region_add(region, 0, 0, window->width, window->height);
		ext_background_effect_surface_v1_set_blur_region(window->effect, region);
		wl_region_destroy(region);
	}
}

/* Recomputes the size in pixels; emits RESIZE when it changed. */
static void rvn_wl_resized(rvn_pwindow_t* window, int force) {
	float scale = rvn_wl_wanted_scale(window);
	int pixel_width, pixel_height;
	if (!window->viewport) {
		/* an integer scale, and a buffer whose size is a multiple of it */
		window->buffer_scale = rvn_maxi(1, (int)scale);
		scale = (float)window->buffer_scale;
	}
	pixel_width = rvn_maxi(1, rvn_wl_round((float)window->width * scale));
	pixel_height = rvn_maxi(1, rvn_wl_round((float)window->height * scale));
	if (!window->viewport) {
		pixel_width = window->width * window->buffer_scale;
		pixel_height = window->height * window->buffer_scale;
	}
	rvn_wl_update_geometry(window);
	if (!force && pixel_width == window->pixel_width && pixel_height == window->pixel_height && scale == window->scale) return;
	window->pixel_width = pixel_width;
	window->pixel_height = pixel_height;
	window->scale = scale;
	if (!window->is_child) {
		rvn_pevent_t event;
		memset(&event, 0, sizeof(event));
		event.type = RVN_PEVENT_RESIZE;
		event.width = pixel_width;
		event.height = pixel_height;
		event.scale = scale;
		rvn_wl_emit(window, &event);
	}
}

