/* ---------------------------------------------------------------------------
 *  Surfaces: outputs entered, preferred scales
 * ------------------------------------------------------------------------- */

static void rvn_wl_surface_enter(void* data, struct wl_surface* surface, struct wl_output* output) {
	rvn_pwindow_t* window = (rvn_pwindow_t*)data;
	RVN_UNUSED(surface);
	if (window->output_count < RVN_WL_MAX_OUTPUTS) window->outputs[window->output_count++] = output;
	if (!window->is_child) rvn_wl_resized(window, R_FALSE);
}

static void rvn_wl_surface_leave(void* data, struct wl_surface* surface, struct wl_output* output) {
	rvn_pwindow_t* window = (rvn_pwindow_t*)data;
	int i;
	RVN_UNUSED(surface);
	for (i = 0; i < window->output_count; i++) {
		if (window->outputs[i] == output) {
			window->outputs[i] = window->outputs[--window->output_count];
			break;
		}
	}
	if (!window->is_child) rvn_wl_resized(window, R_FALSE);
}

static void rvn_wl_surface_preferred_buffer_scale(void* data, struct wl_surface* surface, int32_t factor) {
	rvn_pwindow_t* window = (rvn_pwindow_t*)data;
	RVN_UNUSED(surface);
	window->preferred_buffer_scale = rvn_maxi(1, factor);
	if (!window->is_child) rvn_wl_resized(window, R_FALSE);
}

