/* ---------------------------------------------------------------------------
 *  libdecor frames
 * ------------------------------------------------------------------------- */

static void rvn_wl_decor_configure(struct libdecor_frame* frame, struct libdecor_configuration* configuration, void* user) {
	rvn_pwindow_t* window = (rvn_pwindow_t*)user;
	struct libdecor_state* state;
	int width = 0, height = 0, window_state = 0, maximized = window->maximized;
	if (!g_decor.configuration_get_content_size(configuration, frame, &width, &height)) {
		width = window->width;
		height = window->height;
	}
	if (g_decor.configuration_get_window_state(configuration, &window_state)) {
		maximized = (window_state & RVN_LIBDECOR_STATE_MAXIMIZED) != 0;
	}
	if (window->min_width > 0) width = rvn_maxi(width, window->min_width);
	if (window->min_height > 0) height = rvn_maxi(height, window->min_height);
	state = g_decor.state_new(rvn_maxi(width, 1), rvn_maxi(height, 1));
	g_decor.frame_commit(frame, state, configuration);
	g_decor.state_free(state);
	rvn_wl_apply_configure(window, width, height, maximized);
}

static void rvn_wl_decor_close(struct libdecor_frame* frame, void* user) {
	rvn_pevent_t event;
	RVN_UNUSED(frame);
	memset(&event, 0, sizeof(event));
	event.type = RVN_PEVENT_CLOSE;
	rvn_wl_emit((rvn_pwindow_t*)user, &event);
}

static void rvn_wl_decor_commit(struct libdecor_frame* frame, void* user) {
	RVN_UNUSED(frame);
	wl_surface_commit(((rvn_pwindow_t*)user)->surface);
}

static void rvn_wl_decor_dismiss_popup(struct libdecor_frame* frame, const char* seat, void* user) {
	RVN_UNUSED(frame); RVN_UNUSED(seat); RVN_UNUSED(user);
}

