/* ---------------------------------------------------------------------------
 *  Keyboard
 * ------------------------------------------------------------------------- */

static int rvn_wl_key_test_and_set(RKey key, int down) {
	int index = (int)key, was;
	if (index <= 0 || index >= R_KEY_COUNT) return R_FALSE;
	was = (g_wl.keys_down[index / 8] >> (index % 8)) & 1;
	if (down) g_wl.keys_down[index / 8] |= (uint8_t)(1u << (index % 8));
	else g_wl.keys_down[index / 8] &= (uint8_t)~(1u << (index % 8));
	return was;
}

/* The key as labelled in the active layout: what a shortcut like Ctrl+Z means (as on X11). */
static RKey rvn_wl_key_of(uint32_t keycode) {
	uint32_t layout = g_xkb.state_key_get_layout(g_wl.xkb_state, keycode);
	const uint32_t* syms = NULL;
	RKey key = R_KEY_UNKNOWN;
	if (layout == 0xFFFFFFFFu) layout = 0;
	if (g_xkb.keymap_key_get_syms_by_level(g_wl.keymap, keycode, layout, 0, &syms) > 0) key = rvn_x11_translate_keysym(syms[0]);
	/* layouts with digits on the shifted level (AZERTY) */
	if (key == R_KEY_UNKNOWN && g_xkb.keymap_key_get_syms_by_level(g_wl.keymap, keycode, layout, 1, &syms) > 0) {
		key = rvn_x11_translate_keysym(syms[0]);
	}
	if (key == R_KEY_UNKNOWN) key = rvn_x11_translate_keysym(g_xkb.state_key_get_one_sym(g_wl.xkb_state, keycode));
	return key;
}

static void rvn_wl_emit_text(rvn_pwindow_t* window, uint32_t codepoint) {
	rvn_pevent_t event;
	if (codepoint < 32 || codepoint == 127 || (codepoint >= 0xE000 && codepoint < 0xF900)) return;
	memset(&event, 0, sizeof(event));
	event.type = RVN_PEVENT_TEXT;
	event.codepoint = codepoint;
	rvn_wl_emit(window, &event);
}

/* The text a key produces, through the compose sequences (dead keys) when there are some. */
static void rvn_wl_key_text(rvn_pwindow_t* window, uint32_t keycode) {
	uint32_t symbol;
	if (g_wl.modifiers & (R_MOD_CTRL | R_MOD_ALT)) return;
	symbol = g_xkb.state_key_get_one_sym(g_wl.xkb_state, keycode);
	if (g_wl.compose_state && symbol && g_xkb.compose_state_feed(g_wl.compose_state, symbol) == RVN_XKB_COMPOSE_FEED_ACCEPTED) {
		int status = g_xkb.compose_state_get_status(g_wl.compose_state);
		if (status == RVN_XKB_COMPOSE_COMPOSING) return;
		if (status == RVN_XKB_COMPOSE_CANCELLED) {
			g_xkb.compose_state_reset(g_wl.compose_state);
			return;
		}
		if (status == RVN_XKB_COMPOSE_COMPOSED) {
			char text[64];
			int length = g_xkb.compose_state_get_utf8(g_wl.compose_state, text, sizeof(text));
			const char* cursor = text;
			g_xkb.compose_state_reset(g_wl.compose_state);
			if (length <= 0) return;
			length = rvn_mini(length, (int)sizeof(text) - 1);
			while (cursor < text + length) rvn_wl_emit_text(window, rvn_utf8_decode(&cursor, text + length));
			return;
		}
	}
	rvn_wl_emit_text(window, g_xkb.state_key_get_utf32(g_wl.xkb_state, keycode));
}

static void rvn_wl_repeat_arm(uint32_t keycode) {
	struct itimerspec spec;
	if (g_wl.repeat_fd < 0) return;
	memset(&spec, 0, sizeof(spec));
	g_wl.repeat_key = 0;
	if (keycode && g_wl.repeat_rate > 0 && g_wl.keymap && g_xkb.keymap_key_repeats(g_wl.keymap, keycode)) {
		long interval_ns = 1000000000L / g_wl.repeat_rate;
		g_wl.repeat_key = keycode;
		spec.it_value.tv_sec = g_wl.repeat_delay / 1000;
		spec.it_value.tv_nsec = (long)(g_wl.repeat_delay % 1000) * 1000000L;
		if (spec.it_value.tv_sec == 0 && spec.it_value.tv_nsec == 0) spec.it_value.tv_nsec = 1;
		spec.it_interval.tv_sec = interval_ns / 1000000000L;
		spec.it_interval.tv_nsec = interval_ns % 1000000000L;
	}
	timerfd_settime(g_wl.repeat_fd, 0, &spec, NULL);
}

static void rvn_wl_key_press(rvn_pwindow_t* window, uint32_t keycode, int repeat) {
	rvn_pevent_t event;
	memset(&event, 0, sizeof(event));
	event.type = RVN_PEVENT_KEY;
	event.key = rvn_wl_key_of(keycode);
	event.pressed = R_TRUE;
	event.modifiers = g_wl.modifiers;
	event.repeat = rvn_wl_key_test_and_set(event.key, R_TRUE) || repeat;
	rvn_wl_emit(window, &event);
	if (g_wl.keyboard_window == window) rvn_wl_key_text(window, keycode);
}

/* The repeat timer fired: as many presses as periods went by. */
static void rvn_wl_repeat_fire(void) {
	uint64_t count = 0;
	if (g_wl.repeat_fd < 0 || read(g_wl.repeat_fd, &count, sizeof(count)) != (ssize_t)sizeof(count)) return;
	if (!g_wl.repeat_key || !g_wl.keyboard_window) return;
	if (count > 8) count = 8;
	while (count-- > 0 && g_wl.repeat_key && g_wl.keyboard_window) rvn_wl_key_press(g_wl.keyboard_window, g_wl.repeat_key, R_TRUE);
}

static void rvn_wl_keyboard_keymap(void* data, struct wl_keyboard* keyboard, uint32_t format, int32_t fd, uint32_t size) {
	char* text;
	struct xkb_keymap* keymap;
	RVN_UNUSED(data); RVN_UNUSED(keyboard);
	if (format != WL_KEYBOARD_KEYMAP_FORMAT_XKB_V1 || !g_wl.xkb_context) {
		close(fd);
		return;
	}
	text = (char*)mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
	close(fd);
	if (text == MAP_FAILED) return;
	keymap = g_xkb.keymap_new_from_string(g_wl.xkb_context, text, RVN_XKB_KEYMAP_FORMAT_TEXT_V1, 0);
	munmap(text, size);
	if (!keymap) {
		rvn_error(R_ERROR_PLATFORM, R_SEVERITY_WARNING, "Wayland: the keymap of the compositor cannot be read");
		return;
	}
	if (g_wl.xkb_state) g_xkb.state_unref(g_wl.xkb_state);
	if (g_wl.keymap) g_xkb.keymap_unref(g_wl.keymap);
	g_wl.keymap = keymap;
	g_wl.xkb_state = g_xkb.state_new(keymap);
	g_wl.mod_shift = g_xkb.keymap_mod_get_index(keymap, "Shift");
	g_wl.mod_ctrl = g_xkb.keymap_mod_get_index(keymap, "Control");
	g_wl.mod_alt = g_xkb.keymap_mod_get_index(keymap, "Mod1");
	g_wl.mod_super = g_xkb.keymap_mod_get_index(keymap, "Mod4");
}

static void rvn_wl_keyboard_enter(void* data, struct wl_keyboard* keyboard, uint32_t serial, struct wl_surface* surface, struct wl_array* keys) {
	rvn_pwindow_t* window = rvn_wl_window_of(surface);
	rvn_pevent_t event;
	RVN_UNUSED(data); RVN_UNUSED(keyboard); RVN_UNUSED(keys);
	g_wl.input_serial = serial;
	g_wl.keyboard_window = window;
	if (!window) return;
	memset(&event, 0, sizeof(event));
	event.type = RVN_PEVENT_FOCUS;
	event.focused = R_TRUE;
	rvn_wl_emit(window, &event);
}

static void rvn_wl_keyboard_leave(void* data, struct wl_keyboard* keyboard, uint32_t serial, struct wl_surface* surface) {
	rvn_pwindow_t* window = g_wl.keyboard_window;
	rvn_pevent_t event;
	RVN_UNUSED(data); RVN_UNUSED(keyboard); RVN_UNUSED(serial); RVN_UNUSED(surface);
	g_wl.keyboard_window = NULL;
	rvn_wl_repeat_arm(0);
	/* key releases will go to another window */
	memset(g_wl.keys_down, 0, sizeof(g_wl.keys_down));
	if (g_wl.compose_state) g_xkb.compose_state_reset(g_wl.compose_state);
	if (!window) return;
	memset(&event, 0, sizeof(event));
	event.type = RVN_PEVENT_FOCUS;
	event.focused = R_FALSE;
	rvn_wl_emit(window, &event);
}

static void rvn_wl_keyboard_key(void* data, struct wl_keyboard* keyboard, uint32_t serial, uint32_t time, uint32_t key, uint32_t state) {
	rvn_pwindow_t* window = g_wl.keyboard_window;
	uint32_t keycode = key + 8;   /* evdev codes to the codes of xkb */
	RVN_UNUSED(data); RVN_UNUSED(keyboard); RVN_UNUSED(time);
	g_wl.input_serial = serial;
	if (!window || !g_wl.xkb_state) return;
	if (state == WL_KEYBOARD_KEY_STATE_PRESSED) {
		rvn_wl_key_press(window, keycode, R_FALSE);
		rvn_wl_repeat_arm(keycode);
	} else {
		rvn_pevent_t event;
		if (g_wl.repeat_key == keycode) rvn_wl_repeat_arm(0);
		memset(&event, 0, sizeof(event));
		event.type = RVN_PEVENT_KEY;
		event.key = rvn_wl_key_of(keycode);
		event.pressed = R_FALSE;
		event.modifiers = g_wl.modifiers;
		rvn_wl_key_test_and_set(event.key, R_FALSE);
		rvn_wl_emit(window, &event);
	}
}

static void rvn_wl_keyboard_modifiers(void* data, struct wl_keyboard* keyboard, uint32_t serial, uint32_t depressed,
	uint32_t latched, uint32_t locked, uint32_t group) {
	RVN_UNUSED(data); RVN_UNUSED(keyboard); RVN_UNUSED(serial);
	if (!g_wl.xkb_state) return;
	g_xkb.state_update_mask(g_wl.xkb_state, depressed, latched, locked, 0, 0, group);
	g_wl.modifiers = 0;
#define RVN_MOD(index, flag) \
	if ((index) != RVN_XKB_MOD_INVALID && g_xkb.state_mod_index_is_active(g_wl.xkb_state, (index), RVN_XKB_STATE_MODS_EFFECTIVE) > 0) g_wl.modifiers |= (flag)
	RVN_MOD(g_wl.mod_shift, R_MOD_SHIFT);
	RVN_MOD(g_wl.mod_ctrl, R_MOD_CTRL);
	RVN_MOD(g_wl.mod_alt, R_MOD_ALT);
	RVN_MOD(g_wl.mod_super, R_MOD_SUPER);
#undef RVN_MOD
}

static void rvn_wl_keyboard_repeat_info(void* data, struct wl_keyboard* keyboard, int32_t rate, int32_t delay) {
	RVN_UNUSED(data); RVN_UNUSED(keyboard);
	g_wl.repeat_rate = rate;
	g_wl.repeat_delay = delay;
}

static const struct wl_keyboard_listener g_wl_keyboard_listener = {
	rvn_wl_keyboard_keymap, rvn_wl_keyboard_enter, rvn_wl_keyboard_leave, rvn_wl_keyboard_key,
	rvn_wl_keyboard_modifiers, rvn_wl_keyboard_repeat_info
};

