static void rvn_wl_seat_capabilities(void* data, struct wl_seat* seat, uint32_t capabilities) {
	RVN_UNUSED(data);
	if ((capabilities & WL_SEAT_CAPABILITY_POINTER) && !g_wl.pointer) {
		g_wl.pointer = wl_seat_get_pointer(seat);
		wl_pointer_add_listener(g_wl.pointer, &g_wl_pointer_listener, NULL);
		if (g_wl.cursor_shape_manager) g_wl.cursor_shape = wp_cursor_shape_manager_v1_get_pointer(g_wl.cursor_shape_manager, g_wl.pointer);
	} else if (!(capabilities & WL_SEAT_CAPABILITY_POINTER) && g_wl.pointer) {
		if (g_wl.cursor_shape) wp_cursor_shape_device_v1_destroy(g_wl.cursor_shape);
		g_wl.cursor_shape = NULL;
		if (wl_pointer_get_version(g_wl.pointer) >= 3) wl_pointer_release(g_wl.pointer);
		else wl_pointer_destroy(g_wl.pointer);
		g_wl.pointer = NULL;
		g_wl.pointer_window = NULL;
	}
	if ((capabilities & WL_SEAT_CAPABILITY_KEYBOARD) && !g_wl.keyboard) {
		g_wl.keyboard = wl_seat_get_keyboard(seat);
		wl_keyboard_add_listener(g_wl.keyboard, &g_wl_keyboard_listener, NULL);
	} else if (!(capabilities & WL_SEAT_CAPABILITY_KEYBOARD) && g_wl.keyboard) {
		if (wl_keyboard_get_version(g_wl.keyboard) >= 3) wl_keyboard_release(g_wl.keyboard);
		else wl_keyboard_destroy(g_wl.keyboard);
		g_wl.keyboard = NULL;
		g_wl.keyboard_window = NULL;
		rvn_wl_repeat_arm(0);
	}
}

static void rvn_wl_seat_name(void* data, struct wl_seat* seat, const char* name) {
	RVN_UNUSED(data); RVN_UNUSED(seat); RVN_UNUSED(name);
}

